    val: target,

    duration: 2,
    ease: "power1.out",

    scrollTrigger: {
      trigger: counter,
      start: "top 85%",
      toggleActions: "play none none none"
    },

    onUpdate: () => {

      counter.innerText =
        Math.floor(obj.val) + suffix;

    }

  });

});

</script>

